<script setup>
import { computed, ref, watch } from 'vue';
import { USER_FACING_ERROR } from '../../../shared/userFacingError.js';
import { artifactUrl, canCancel, canResume, fileAliases, issueText, parseObject, pretty, runLabels } from '../assetAppsModel.js';
const props = defineProps({ run: { type: Object, required: true }, definition: Object, files: { type: Array, default: () => [] }, busy: Boolean });
const emit = defineEmits(['resume', 'cancel']);
const inputText = ref('{}'), fileBindings = ref({}), confirmed = ref(false), retryUnknown = ref(false), error = ref(''), skillAnswer = ref('');
watch(() => props.run.id, () => { inputText.value = pretty(props.run.input || {}); fileBindings.value = { ...(props.run.fileBindings || {}) }; confirmed.value = false; retryUnknown.value = false; error.value = ''; }, { immediate: true });
const aliases = computed(() => fileAliases(props.definition));
const skillQuestion = computed(() => props.run.waiting?.kind === 'skill_question' ? props.run.waiting.question : null);
watch(() => skillQuestion.value?.id, () => { skillAnswer.value = ''; error.value = ''; });
const node = id => props.definition?.nodes?.find(item => item.id === id);
function resume() {
  try {
    const body = { revision: props.run.revision };
    if (skillQuestion.value) {
      if (!skillAnswer.value.trim()) throw new Error('请回答当前 Skill 的问题。');
      body.skillAnswer = { questionId: skillQuestion.value.id, revision: skillQuestion.value.revision, answer: skillAnswer.value.trim() };
    } else if (props.run.status === 'awaiting_input') body.input = parseObject(inputText.value, '补充输入');
    if (!skillQuestion.value && ['awaiting_input','awaiting_authorization'].includes(props.run.status)) body.fileBindings = { ...fileBindings.value };
    if (props.run.status === 'awaiting_authorization') { if (!confirmed.value) throw new Error('请先确认本次授权。'); body.authorizationConfirmed = true; }
    if (retryUnknown.value) body.retryUnknown = true;
    error.value = ''; emit('resume', body);
  } catch (cause) { error.value = cause.message; }
}
</script>

<template>
  <article class="asset-run" :data-asset-run-id="run.id" :data-status="run.status" aria-label="应用运行详情">
    <header class="asset-run-head"><div><span class="asset-run-eyebrow">{{ run.mode === 'verification' ? 'VALIDATION / 验证运行' : 'RUN / 本次运行' }}</span><h3>{{ runLabels[run.status] || run.status }}</h3><small>版本 {{ run.versionId }} · {{ run.id }}</small></div><button v-if="canCancel(run)" type="button" class="secondary-button" :disabled="busy" @click="emit('cancel')">取消本次运行</button></header>
    <p class="asset-run-note">结果逐步保留。刷新或关闭页面不会取消后台运行。</p>
    <div v-if="run.error" class="asset-run-error" role="alert">{{ USER_FACING_ERROR }}</div>
    <ol class="asset-run-steps"><li v-for="(step,index) in run.steps || []" :key="step.nodeId"><span class="asset-run-marker" :class="step.status">{{ step.status === 'succeeded' ? '✓' : index + 1 }}</span><div><div class="asset-run-step-head"><strong>{{ node(step.nodeId)?.title || step.nodeId }}</strong><span>{{ runLabels[step.status] || step.status }}</span></div><p v-if="step.error" class="asset-run-step-error">{{ USER_FACING_ERROR }}</p><details><summary>本步骤实际输入与交付</summary><h4>输入</h4><pre>{{ pretty(step.resolvedInput || {}) }}</pre><h4>结果</h4><pre v-if="step.status === 'succeeded' && !step.error">{{ pretty(step.result ?? {}) }}</pre><p v-else-if="step.error">{{ USER_FACING_ERROR }}</p><p v-if="step.skillCallId">Skill 执行记录：{{ step.skillCallId }}</p><a v-for="file in step.artifacts || []" :key="file.id || file.name" :href="artifactUrl(file.downloadUrl) || undefined" :aria-disabled="!artifactUrl(file.downloadUrl)" download>{{ file.name }}</a></details></div></li></ol>
    <section v-if="run.waiting || canResume(run)" class="asset-run-waiting"><h4>{{ run.status === 'awaiting_confirmation' ? '检查这一步，然后继续' : runLabels[run.status] || '等待处理' }}</h4><p v-if="run.waiting?.reason">{{ ['failed','interrupted'].includes(run.status) ? USER_FACING_ERROR : issueText(run.waiting.reason) }}</p><ul v-if="run.waiting?.missing?.length && !['failed','interrupted'].includes(run.status)"><li v-for="(item,index) in run.waiting.missing" :key="index">{{ issueText(item) }}</li></ul><p v-if="['failed','interrupted'].includes(run.status)">继续前会核对原版本、输入及已完成结果；修改实现后应保存新版本并重新运行。</p><form v-if="canResume(run)" @submit.prevent="resume"><label v-if="skillQuestion">{{ skillQuestion.prompt }}<textarea v-model="skillAnswer" :disabled="busy" rows="4" required placeholder="回答当前问题，继续本节点任务" aria-label="回答 Skill 问题" /></label><label v-else-if="run.status === 'awaiting_input'">补充本次输入（JSON）<textarea v-model="inputText" :disabled="busy" rows="5" spellcheck="false" /></label><template v-if="!skillQuestion && ['awaiting_input','awaiting_authorization'].includes(run.status)"><label v-for="alias in aliases" :key="alias">本次文件 · {{ alias }}<select v-model="fileBindings[alias]" :disabled="busy"><option value="">请选择文件</option><option v-for="file in files" :key="file.id" :value="file.id">{{ file.name }}</option></select></label></template><label v-if="run.status === 'awaiting_authorization'" class="asset-run-check"><input v-model="confirmed" type="checkbox" :disabled="busy" />确认按上方范围授予本次运行所需权限</label><label v-if="['failed','interrupted'].includes(run.status)" class="asset-run-check"><input v-model="retryUnknown" type="checkbox" :disabled="busy" />若外部调用结果未知，我已核对并明确允许重新尝试</label><p v-if="error" role="alert" class="asset-run-step-error">{{ USER_FACING_ERROR }}</p><button type="submit" class="primary-button" :disabled="busy">{{ run.status === 'awaiting_confirmation' ? '检查完成，继续下一步' : '从当前进度继续' }}</button></form></section>
    <section v-if="run.result != null && !['failed','interrupted'].includes(run.status)" class="asset-run-result"><h4>本次最终结果</h4><pre>{{ pretty(run.result) }}</pre></section>
    <div v-if="run.artifacts?.length" class="asset-run-artifacts"><template v-for="file in run.artifacts" :key="file.id"><figure v-if="file.mediaType === 'image/png' && artifactUrl(file.downloadUrl)"><img :src="artifactUrl(file.downloadUrl)" :alt="file.name" loading="lazy" /><figcaption>{{ file.name }}</figcaption></figure><a v-if="artifactUrl(file.downloadUrl)" :href="artifactUrl(file.downloadUrl) + '?download=1'" download>↓ {{ file.name }}</a></template></div>
  </article>
</template>

<style scoped>
.asset-run{border:1px solid var(--line);border-radius:16px;padding:24px;background:var(--surface);margin-top:22px;min-width:0}.asset-run-head{display:flex;justify-content:space-between;gap:14px;align-items:start}.asset-run-eyebrow{font-size:10px;letter-spacing:.12em;color:var(--build-ink)}.asset-run-head h3{font-size:21px;margin:9px 0}.asset-run-head small{font-size:10px;color:var(--dim);overflow-wrap:anywhere}.asset-run-note{font-size:12px;color:var(--muted);line-height:1.8}.asset-run-error{color:var(--danger);background:var(--error-wash);padding:13px;border-radius:8px;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}.asset-run-steps{list-style:none;padding:10px 0;margin:15px 0}.asset-run-steps>li{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);min-width:0}.asset-run-steps>li>div{flex:1;min-width:0}.asset-run-marker{width:23px;height:23px;flex:none;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;font-size:11px;color:var(--muted)}.asset-run-marker.succeeded{color:var(--success-ink);background:var(--success-wash)}.asset-run-marker.failed{color:var(--danger);background:var(--error-wash)}.asset-run-step-head{display:flex;justify-content:space-between;gap:10px;font-size:13px;line-height:1.8}.asset-run-step-head span{font-size:11px;color:var(--muted)}.asset-run details{margin-top:7px;font-size:12px}.asset-run summary{cursor:pointer;color:var(--build-ink);padding:5px 0}.asset-run h4{font-size:13px;margin:12px 0 8px}.asset-run pre{font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface-2);border-radius:8px;padding:13px;max-height:320px;overflow:auto}.asset-run a{display:inline-block;font-size:12px;color:var(--build-ink);margin:7px 14px 7px 0}.asset-run-waiting{border-left:3px solid #b88a42;background:var(--warning-wash);padding:14px 18px;margin:18px 0}.asset-run-waiting h4{margin-top:0}.asset-run-waiting p,.asset-run-waiting li{font-size:12px;line-height:1.85;color:var(--warning-ink)}.asset-run label{display:grid;gap:7px;font-size:12px;margin:13px 0}.asset-run input:not([type=checkbox]),.asset-run textarea,.asset-run select{width:100%;border:1px solid var(--line);border-radius:7px;padding:9px;font:inherit;background:var(--surface);color:var(--text);resize:vertical;min-width:0}.asset-run .asset-run-check{display:flex;gap:8px;align-items:start;line-height:1.8}.asset-run-step-error{color:var(--danger);font-size:12px;line-height:1.8;overflow-wrap:anywhere}.asset-run-artifacts figure{margin:14px 0}.asset-run-artifacts img{display:block;max-width:100%;height:auto;border:1px solid var(--line);border-radius:8px}.asset-run-artifacts figcaption{font-size:11px;color:var(--muted);margin-top:7px}@media(max-width:620px){.asset-run{padding:16px}.asset-run-head{flex-wrap:wrap}.asset-run-waiting{padding:12px}.asset-run-step-head{flex-wrap:wrap}.asset-run-head h3{font-size:18px}}
</style>
